window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-880682731cb62977"]={"versions": [{"id": "FIG-880682731cb62977", "releases": ["R1.5.1", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm (<code>class HM_HealthChannel</code>) im Kontext des Health Monitoring (AUTOSAR Adaptive Platform). Es spezifiziert die statische Modellstruktur eines Überwachungskanals (<code>HealthChannel</code>) und dessen zugeordneten Gesundheitszuständen (<code>HealthStatus</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert zwei Klassen und eine gerichtete Kompositionsbeziehung:</p>\n<ul class=\"fig-list\">\n<li><strong><code>HealthChannel</code></strong>: Repräsentiert den Gesundheitskanal mit den privaten Attributen:</li>\n<li><code>- Name</code>: Bezeichner des Kanals.</li>\n<li><code>- ID</code>: Eindeutige numerische Kennung.</li>\n<li><code>- NumberOfInstances</code>: Anzahl der Instanzen des Kanals.</li>\n<li><code>- HealthStatusInitValue</code>: Initialer Zustand bzw. Statuswert des Kanals.</li>\n<li><strong><code>HealthStatus</code></strong>: Repräsentiert die möglichen Zustände des Kanals mit den privaten Attributen:</li>\n<li><code>- Name</code>: Bezeichner des Statuswerts.</li>\n<li><code>- ID</code>: Eindeutige Kennung des Statuswerts.</li>\n<li><strong>Beziehung</strong>: Komposition (ausgefüllte Raute auf Seiten von <code>HealthChannel</code>) zu <code>HealthStatus</code>, die besagt, dass ein <code>HealthChannel</code> die zugehörigen <code>HealthStatus</code>-Elemente als Teil seiner Definition besitzt und verwaltet.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Klassendiagramm stellt die Abbildung keine dynamischen Interaktionen, Nachrichtenaustausche oder zeitlichen Abläufe dar. Das implizierte Laufzeitverhalten umfasst die Initialisierung des <code>HealthChannel</code> mit dem durch <code>HealthStatusInitValue</code> definierten Anfangszustand sowie die Auswertung bzw. Weiterleitung auftretender <code>HealthStatus</code>-Meldungen über die instanziierten Kanäle.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Modellierung definiert verbindliche Konfigurations- und Datenstrukturen für das Health Monitoring. Implementierungen müssen sicherstellen, dass konfigurierte Gesundheitskanäle über eindeutige Identifikatoren (<code>ID</code>) verfügen, die konfigurierte Anzahl an Instanzen (<code>NumberOfInstances</code>) bereitstellen und beim Start auf den definierten <code>HealthStatusInitValue</code> initialisiert werden. Zustandsmeldungen referenzieren die definierten <code>HealthStatus</code>-Elemente anhand ihrer ID bzw. ihres Namens.</p>"}, {"id": "FIG-101535857e342d9a", "releases": ["R18-03_R1.4.0", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm (<code>class HM_HealthChannel</code>) im Kontext des Health Monitoring (AUTOSAR Adaptive Platform). Es spezifiziert die statische Modellstruktur eines Überwachungskanals (<code>HealthChannel</code>) und dessen zugeordneten Gesundheitszuständen (<code>HealthStatus</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert zwei Klassen und eine gerichtete Kompositionsbeziehung:</p>\n<ul class=\"fig-list\">\n<li><strong><code>HealthChannel</code></strong>: Repräsentiert den Gesundheitskanal mit den privaten Attributen:</li>\n<li><code>- Name</code>: Bezeichner des Kanals.</li>\n<li><code>- ID</code>: Eindeutige numerische Kennung.</li>\n<li><code>- NumberOfInstances</code>: Anzahl der Instanzen des Kanals.</li>\n<li><strong><code>HealthStatus</code></strong>: Repräsentiert die möglichen Zustände des Kanals mit den privaten Attributen:</li>\n<li><code>- Name</code>: Bezeichner des Statuswerts.</li>\n<li><code>- ID</code>: Eindeutige Kennung des Statuswerts.</li>\n<li><strong>Beziehung</strong>: Komposition (ausgefüllte Raute auf Seiten von <code>HealthChannel</code>) zu <code>HealthStatus</code>, die besagt, dass ein <code>HealthChannel</code> die zugehörigen <code>HealthStatus</code>-Elemente als Teil seiner Definition besitzt und verwaltet.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Klassendiagramm stellt die Abbildung keine dynamischen Interaktionen, Nachrichtenaustausche oder zeitlichen Abläufe dar. Das implizierte Laufzeitverhalten umfasst die Verwaltung und Auswertung von <code>HealthStatus</code>-Meldungen über die instanziierten <code>HealthChannel</code>-Kanäle.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Modellierung definiert verbindliche Konfigurations- und Datenstrukturen für das Health Monitoring. Implementierungen müssen sicherstellen, dass konfigurierte Gesundheitskanäle über eindeutige Identifikatoren (<code>ID</code>) verfügen und die konfigurierte Anzahl an Instanzen (<code>NumberOfInstances</code>) unterstützen. Zustandsmeldungen referenzieren die definierten <code>HealthStatus</code>-Elemente anhand ihrer ID bzw. ihres Namens.</p>"}], "trans": [{"from": "FIG-880682731cb62977", "to": "FIG-101535857e342d9a", "fr": "R1.5.1", "tr": "R18-03_R1.4.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Attribut <code>HealthStatusInitValue</code> in Klasse <code>HealthChannel</code> entfernt.</li>\n</ul>"}, {"from": "FIG-101535857e342d9a", "to": "FIG-880682731cb62977", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-03", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Attribut <code>HealthStatusInitValue</code> in Klasse <code>HealthChannel</code> hinzugefügt.</li>\n</ul>"}]};
